INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES
('doc-new-theory-1', 'theory', 'new-theory-1', 'new-theory-1', 'همگرایی رسانه‌ای', 'Media Convergence', 'theory', 'همگرایی رسانه‌ای فرآیندی است که در آن محتوا، رسانه، صنعت، فناوری و مخاطب در یک اکوسیستم واحد ادغام می‌شوند. هنری جنکینز آن را نه صرفا‌ً فنی، بلکه فرهنگی و اقتصادی می‌داند: «همگرایی به معنای حرکت محتوا از چند کانال رسانه‌ای است». در بافت ایران، همگرایی از تلویزیون و رادیو به پلتفرم‌های پیام‌رسان و شبکه‌های اجتماعی (شبکه‌های داخلی و خارجی) را در بر می‌گیرد.', NULL, 'fa', NULL, 'international', 'b9241985b07f341ac87fc35f9b4b3eff494743f2cb5355df4f3afcc78ee4da52', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-2', 'theory', 'new-theory-2', 'new-theory-2', 'دهکده جهانی و جهانی‌شدن فرهنگی', 'The Global Village & Cultural Globalization', 'theory', 'مارشال مکلوهان با مفهوم «دهکده جهانی» ادعا کرد فناوری‌های ارتباطی، جهان را به روستایی کوچک تبدیل کرده‌اند که همه در آن همسایه‌اند. این مفهوم پایه‌گذار نظریه‌های جهانی‌شدن فرهنگی شد. گراهام ترک و دیگران آن را در قالب «جهانی‌شدن فرهنگی» بازخوانی کردند: جریان‌های فرهنگی یک‌سویه از مرکز به پیراهن. در ایران، این نظریه برای تحلیل نفوذ فرهنگ‌های غربی از طریق رسانه‌های دیجیتال و مقایسه با «جهانی‌محلی‌شدن» (glocalization) کاربرد دارد.', NULL, 'fa', NULL, 'international', '92239e6b675d06aac911a81363f7da293509c2503816a3d0f4993bff91a5acff', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-3', 'theory', 'new-theory-3', 'new-theory-3', 'سرمایه‌داری نظارتی', 'Surveillance Capitalism', 'theory', 'شوشانا زابوف استدلال می‌کند که شرکت‌های فناوری (گوگل، فیس‌بوک و...) از داده‌های رفتاری کاربران به‌عنوان «مواد خام» برای پیش‌بینی و کنترل رفتار سود بردن می‌کنند. این فرآیند «پیش‌بینی رفتار» (behavioural futures) می‌سازد که در بازار «بازاریابی خودکار» فروخته می‌شوند. زابوف آن را «نسل جدید سرمایه‌داری» می‌نامد که با «سرمایه‌داری داده‌ای» فرق دارد. در ایران، پلتفرم‌های داخلی (اسنپ، دیجی‌کالا) و شبکه‌های اجتماعی هم‌سو با این الگو عمل می‌کنند.', NULL, 'fa', NULL, 'international', '37b920a441f706af4f365f6b0a53e1c7d4c47127de166b25ede0860b56be2141', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-4', 'theory', 'new-theory-4', 'new-theory-4', 'سرمایه‌داری پلتفرمی / اقتصاد پلتفرم', 'Platform Capitalism & Platform Economy', 'theory', 'نیک سرنیک استدلال می‌کند که پلتفرم‌های دیجیتال (آمازون، آیربی‌انبی، اوبر) فرم جدیدی از سرمایه‌داری هستند که با «مالکیت انحصاری داده» و «اقتصاد شبکه» کار می‌کنند. تفاوت کلیدی با سرمایه‌داری کلاسیک: پلتفرم «زیرساخت مشترک» است که همزمان به دو طرف بازار خدمت می‌کند. در ایران، پلتفرم‌های ابر و اقتصاد دیجیتال نشان‌دهنده رشد این الگو است.', NULL, 'fa', NULL, 'international', '9151009fd120c34a3c154422ffc082521a79c23c80aacf29a044f44029594d58', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-5', 'theory', 'new-theory-5', 'new-theory-5', 'اقتصاد توجه', 'Attention Economy', 'theory', 'هربرت سایمون در ۱۹۷۱ نوشت: «سرشاری اطلاعات به معنای کمبود توجه است». داونتون و بک در ۱۹۹۹ مفهوم «اقتصاد توجه» را رسمی کردند: در دنیایی که اطلاعات رایگان است، توجه کاربر کمیاب‌ترین منبع است و رسانه‌ها و پلتفرم‌ها برای کسب آن رقابت می‌کنند. این نظریه پایه اقتصاد مدل‌های کسب‌وکار رسانه دیجیتال (تبلیغات هدفمند، درگیرسازی کاربر) است.', NULL, 'fa', NULL, 'international', '5f0bf32663e89254eebce0d297942e7cb02f5b91a07e14f25cbc66bb1f4ba7c9', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-6', 'theory', 'new-theory-6', 'new-theory-6', 'استعمار داده', 'Data Colonialism', 'theory', 'مِرن مِترن استدلال می‌کند که استخراج داده از جوامع حاشیه (peripheral) توسط شرکت‌های فناوری مرکز (center) فرمی از استعمار نو (neocolonialism) است. داده «خام» از جنوب جهانی استخراج، در شمال پردازش و سود آن به مرکز بازمی‌گردد — شبیه استعمار کلاسیک. این نظریه پایه‌گذار مباحث «عدالت داده» و «حاکمیت داده» شد.', NULL, 'fa', NULL, 'international', 'f3f738293283a6aec5f12d082156580c9e04305e6682c02865b7dcda345f1f9f', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-7', 'theory', 'new-theory-7', 'new-theory-7', 'حاکمیت الگوریتمی', 'Algorithmic Governance', 'theory', 'حاکمیت الگوریتمی مطالعه‌ی نحوه استفاده از الگوریتم‌ها برای اداره‌ی نظام‌های اجتماعی، اقتصادی و سیاسی است. سرنیک و زاک (۲۰۱۷) «الگوریتم‌های پلتفرمی» را به‌عنوان مکانیسم‌های تصمیم‌گیری پنهان تحلیل کردند. گرِیَم و هاتِر (۲۰۲۰) آن را به «حاکمیت الگوریتمی» گسترش دادند: الگوریتم‌ها دولت‌ها، نظام‌های قضایی و بهداشتی را اداره می‌کنند.', NULL, 'fa', NULL, 'international', 'fb7bef144539032cff27f641ea2fc352ab3b5e92744d8b4ad700953ac1b1a3b8', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-8', 'theory', 'new-theory-8', 'new-theory-8', 'پسا-حقیقت', 'Post-Truth / Post-Truth Politics', 'theory', '«پسا-حقیقت» وضعیتی است که در آن حقایق عینی کمتر از احساسات و باورهای شخصی بر افکار عمومی تأثیر می‌گذارند. آکسفورد در ۲۰۱۶ آن را «واژه سال» انتخاب کرد. کُسنْتینو (۲۰۲۰) آن را به‌عنوان چارچوب نظری تحلیل کرد: در پسا-حقیقت، «واقعت‌سازی» جایگزین «واقعت‌یابی» می‌شود. در ایران، خبر جعلی و جنگ روایت نمونه‌هایی از پسا-حقیقت است.', NULL, 'fa', NULL, 'international', '381104a45708d85c31089c8ffd12f6c9a1dd63e47631d66348ef7df183611883', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-9', 'theory', 'new-theory-9', 'new-theory-9', 'امپریالیسم رسانه‌ای', 'Media Imperialism', 'theory', 'دنیل اشیلر در ۱۹۷۵ استدلال کرد که شرکت‌های رسانه‌ای آمریکایی فرمی از امپریالیسم اقتصادی و فرهنگی اجرا می‌کنند: «رسانه به‌عنوان ابزار نفوذ فرهنگی». این نظریه پایه‌گذار مباحث «امپریالیسم فرهنگی» و «هژمونی فرهنگی» شد. در ایران، امپریالیسم رسانه‌ای به‌شکل نفوذ محتوای غربی از طریق پلتفرم‌های دیجیتال دیده می‌شود.', NULL, 'fa', NULL, 'international', '142b0c54e5f53403fc418f2fbe3f0ea7923c1d7262bdf326e4d1f4d877f75acd', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-10', 'theory', 'new-theory-10', 'new-theory-10', 'ارتباطات دنیای سوم / ارتباطات توسعه', 'Third World Communication & Media Development', 'theory', '«ارتباطات توسعه» (Development Communication) مکتبی از مطالعات رسانه است که رسانه را ابزاری برای توسعه‌ی اقتصادی و اجتماعی جوامع حاشیه می‌داند. روجِرس و استاینر (۱۹۶۲) «نظریه‌ی دو جریان» را مطرح کردند. جوساوالا (۱۹۷۹) آن را در قالب «ارتباطات دنیای سوم» بازنویسی کرد: «رسانه‌ها نه‌فقط انعکاس‌دهنده، بلکه شکل‌دهنده‌ی توسعه‌اند».', NULL, 'fa', NULL, 'international', '714eb5a539629c05f73d14d5e31a8f5cd0cad5d8b00151bf2b8b4b030ce607b3', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-11', 'theory', 'new-theory-11', 'new-theory-11', 'شکاف دیجیتال', 'Digital Divide', 'theory', 'شکاف دیجیتال به نابرابری در دسترسی، استفاده و بهره‌وری از فناوری‌های دیجیتال بین گروه‌های مختلف اشاره دارد. جان ون دییک (۲۰۰۵) آن را در سه سطح تحلیل کرد: دسترسی (access)، استفاده (usage)، و بهره‌وری (benefits). در ایران، شکاف دیجیتال بین شهر و روستا، بین جوان و پیر، و بین لایه‌های درآمدی مختلف دیده می‌شود.', NULL, 'fa', NULL, 'international', 'ef59c0618722c757e58706f5cdf8d6345c3b2319fa56e0523f8176d7a2e9300e', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-12', 'theory', 'new-theory-12', 'new-theory-12', 'حاکمیت دیجیتال / تنظیم‌گری پلتفرمی', 'Digital Governance & Platform Regulation', 'theory', 'حاکمیت دیجیتال مطالعه‌ی چگونگی اداره‌ی فضای دیجیتال توسط دولت‌ها، شرکت‌ها و جامعه مدنی است. «تنظیم‌گری پلتفرمی» فرم جدیدی از تنظیم‌گری است که به‌جای تنظیم‌کننده‌ی دولت، خود پلتفرم را تنظیم‌کننده می‌داند (self-regulation). در ایران، فیلترینگ و تنظیم‌گری دولت در فضای دیجیتال نمونه‌هایی از این حوزه است.', NULL, 'fa', NULL, 'international', '62a528d61b625ddf2ff22adcc0f111b0655f1383e8aaf424e5a87bfdc2cb6405', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-13', 'theory', 'new-theory-13', 'new-theory-13', 'الگوریتم‌سازی / حباب فیلتر', 'Algorithmic Curation & Filter Bubble', 'theory', 'الی پارِیسِر در ۲۰۱۱ مفهوم «حباب فیلتر» را مطرح کرد: الگوریتم‌های پلتفرم‌ها بر اساس تاریخچه‌ی جست‌وجو و رفتار کاربر، محتوای شخصی‌سازی‌شده‌ای را نمایش می‌دهند که کاربر را در «حباب» اطلاعاتی محبوس می‌کند. این فرآیند به قطبی‌سازی و کاهش درک مشترک واقعیت می‌انجامد.', NULL, 'fa', NULL, 'international', 'c41f31d0bd8c198ec4914a8edab8bf2a0465cac77c948e3469194e5637bd28fc', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-14', 'theory', 'new-theory-14', 'new-theory-14', 'هژمونی فرهنگی و نظریه کدگذاری/بازنمایی', 'Cultural Hegemony & Encoding/Decoding Theory', 'theory', 'آنتونیو گرامشی مفهوم «هژمونی فرهنگی» را مطرح کرد: حاکمیت نه از طریق زور، بلکه از طریق تفوق فرهنگی و ایدئولوژیک. استیون هال (۱۹۷۳) آن را در قالب «نظریه کدگذاری/بازنمایی» (encoding/decoding) به رسانه‌ها آورد: پیام رسانه‌ای توسط فرستنده کدگذاری، و توسط مخاطب بازنمایی می‌شود — و مخاطب می‌تواند پیام را به‌صورت «حاکمانه»، «مقاومتی» یا «مخلوط» بازنمایی کند.', NULL, 'fa', NULL, 'international', 'f3e1172b7bb28bc7e8e0a6b05db4f3ac4510da0db2ce2270fd391beb8d92982b', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-theory-15', 'theory', 'new-theory-15', 'new-theory-15', 'مدل بهینه رسانه مبتنی بر اصول اسلامی', 'Optimal Media Model based on Islamic Principles', 'model', 'پیام تیرانداز در این مدل، مبانی نظری «رسانه بهینه» را از اصول اسلامی استخراج می‌کند: صداقت، عدالت، مسئولیت، و احترام به کرامت انسانی. این مدل برخلاف مدل‌های غربی، منبع ارزش‌ها خود را در قرآن و سنت می‌داند. در بافت ایران، این مدل می‌تواند مبنای طراحی سیاست‌های رسانه‌ای، اخلاق حرفه‌ای روزنامه‌نگاری، و تنظیم‌گری رسانه در جمهوری اسلامی قرار گیرد.', NULL, 'fa', 'ایران', 'iranian', 'cfeadf1b68ed1c3b6116000dab026717d4b0a659e1c7df37afa5502e47072bfb', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-new-theory-1-1', 'doc-new-theory-1', 'definition', 'تعریف', 'همگرایی رسانه‌ای (Media Convergence) فرآیندی است که در آن محتوا، رسانه، صنعت، فناوری و مخاطب در یک اکوسیستم واحد ادغام می‌شوند. هنری جنکینز آن را نه صرفا‌ً فنی، بلکه فرهنگی و اقتصادی می‌داند: «همگرایی به معنای حرکت محتوا از چند کانال رسانه‌ای است». ریشه‌ی این مفهوم به نظریه‌ی «دهکده‌ی جهانی» مارشال مکلوهان بازمی‌گردد و جنکینز آن را در سال ۱۹۹۴ (و نسخه‌ی بازنویسی‌شده در ۲۰۰۶، Convergence Culture) صورت‌بندی کرد.', 'b09a3358e6392a2d2643bd35977c1b4fdbb5cd57340c8a7b62faa8550590af78', 1, NOW(), NOW()),
('sec-new-theory-1-2', 'doc-new-theory-1', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری جنکینز همگرایی را پدیده‌ای چندبُعدی می‌داند: بیداری فناوری (پخش‌کنندگان دیجیتال)، تغییر صنعتی (ادغام ناشران و پلتفرم‌ها) و مهاجرات مخاطب (رفتار کاربر بین چند رسانه). همگرایی نه یک «چیز» بلکه یک «فرآیند» است و بر تقاطع محتوا، صنعت، فناوری و مخاطب تمرکز دارد. ریشه‌ی آن در مفهوم «دهکده‌ی جهانی» مکلوهان (۱۹۶۴) است؛ جایی که فناوری‌های ارتباطی جهان را به فضایی فشرده تبدیل می‌کنند.', '899f4ef2aaf3489f488c200ec55f85e0ac7d9e46a9f5e5b46dd7d9d23f42cefe', 2, NOW(), NOW()),
('sec-new-theory-1-4', 'doc-new-theory-1', 'applications', 'کاربردها', 'تحلیل انتقال مخاطب از رسانه‌های دولتی (IRIB) به پلتفرم‌های دیجیتال؛ همگرایی فرهنگ «تلویزیونی» با فرهنگ «پلتفرمی»؛ چالش تنظیم‌گری در دنیای همگرایی (چرا تنظیم‌کننده نمی‌داند چگونه پلتفرم را مثل تلویزیون تنظیم کند).', '6dba041916f9579fe81ddb22c1dfdaa6576b5926f0b9fb1ae85363b1b85879ac', 4, NOW(), NOW()),
('sec-new-theory-1-10', 'doc-new-theory-1', 'references', 'منابع', 'Jenkins, H. (2006). Convergence Culture: Where Old and New Media Collide. NYU Press. — ویکی‌پدیا: Media convergence.', '38ced7e4b714dd1b779747c5660c2284da5534bc3e8c0a8fe781f8bfcc75ee8f', 10, NOW(), NOW()),
('sec-new-theory-2-1', 'doc-new-theory-2', 'definition', 'تعریف', 'مکلوهان با مفهوم «دهکده جهانی» (Global Village) ادعا کرد فناوری‌های ارتباطی، جهان را به روستایی کوچک تبدیل کرده‌اند که همه در آن همسایه‌اند. این مفهوم (۱۹۶۴، For Your Eyes Only) پایه‌گذار نظریه‌های جهانی‌شدن فرهنگی شد. گراهام ترک (۱۹۹۵، Globalization and Culture) آن را در قالب «جهانی‌شدن فرهنگی» بازخوانی کرد: جریان‌های فرهنگی یک‌سویه از مرکز به پیراهن.', 'c51e8b2dd073063107cc17fd55d70d8f0ee09f1d9ab01e6e7bfca22c60c428bd', 1, NOW(), NOW()),
('sec-new-theory-2-2', 'doc-new-theory-2', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری «دهکده جهانی» بر این فرض استوار است که فناوری‌های الکترونیک (رادیو، تلویزیون، اینترنت) مرزهای جغرافیایی را حذف کرده و جهان را به فضایی فشرده و همسایه تبدیل می‌کنند. «جهانی‌شدن فرهنگی» (ترک) این ایده را با تأکید بر جریان‌های فرهنگی یک‌سویه از مرکز به حاشیه گسترش می‌دهد و در تقابل با «محلی‌سازی» و «جهانی‌محلی‌شدن» (glocalization) قرار می‌گیرد.', 'be3399df9993bc3ef43e622f2979ba5ba50608a60fa47359b52e302c44d4c0ed', 2, NOW(), NOW()),
('sec-new-theory-2-4', 'doc-new-theory-2', 'applications', 'کاربردها', 'تحلیل «جریان یک‌سویه‌ی اخبار جهانی» (مدخل ۱۹۳) در بافت ایرانی؛ نقد امپریالیسم فرهنگی از طریق پلتفرم‌های غربی؛ مقایسه با «نزدیکی فرهنگی» (مدخل ۲۱۶) و «جهانی‌محلی‌شدن» (مدخل ۴۵۷).', '292e428cbd20acd6948501ffa38dae5ead2f4e31c9f17b4f0ab5490e66d0eec3', 4, NOW(), NOW()),
('sec-new-theory-2-10', 'doc-new-theory-2', 'references', 'منابع', 'McLuhan, M. (1964). For Your Eyes Only. Bantam. — ویکی‌پدیا: Global village.', '0fdd78836c42c5cfa5ea5a9bd0602e3cab938b0e0654179f3783ba5cf6db5860', 10, NOW(), NOW()),
('sec-new-theory-3-1', 'doc-new-theory-3', 'definition', 'تعریف', 'زابوف استدلال می‌کند که شرکت‌های فناوری (گوگل، فیس‌بوک و...) از داده‌های رفتاری کاربران به‌عنوان «مواد خام» برای پیش‌بینی و کنترل رفتار سود بردن می‌کنند. این فرآیند «پیش‌بینی رفتار» (behavioural futures) می‌سازد که در بازار «بازاریابی خودکار» (automated marketing) فروخته می‌شوند. زابوف آن را «نسل جدید سرمایه‌داری» می‌نامد که با «سرمایه‌داری داده‌ای» (data capitalism) فرق دارد (۲۰۱۹، The Age of Surveillance Capitalism).', '9105233eda1720f90f2739bc31a11c5e33dbecef03bdd6b01933590a4442dbe5', 1, NOW(), NOW()),
('sec-new-theory-3-2', 'doc-new-theory-3', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری زابوف سه مؤلفه دارد: (۱) استخراج داده‌های رفتاری، (۲) ساخت مدل‌های پیش‌بینی رفتار، (۳) فروش «آینده‌های رفتاری» در بازارهای نظارتی. تفاوت کلیدی با سرمایه‌داری کلاسیک، «جنگ با انکار» (logistics of prediction) و بهره‌برداری از رفتار بدون رضایت آگاهانه است. این نظریه با «حاکمیت الگوریتمی» (شبکه ۶) پیوند دارد.', 'f855ddf905d4bee3c0881da86fcb36aed97bf3e9c9f588276baba8483d101b54', 2, NOW(), NOW()),
('sec-new-theory-3-4', 'doc-new-theory-3', 'applications', 'کاربردها', 'تحلیل مدل کسب‌وکار پلتفرم‌های ایرانی (اسنپ، دیجی‌کالا، اینستاگرام‌های داخلی) از منظر سرمایه‌داری نظارتی؛ رابطه «داده‌نظارتی» (مدخل ۲۸۵) با نظارت دولت و شرکت؛ چالش اخلاقی و قانونی جمع‌آوری داده در بافت ایرانی.', '3bf1c0bbe2ca0e0fde0ea537cb6fc234cc695fbdc388d65c20cdd6d69f63f8f6', 4, NOW(), NOW()),
('sec-new-theory-3-10', 'doc-new-theory-3', 'references', 'منابع', 'Zuboff, S. (2019). The Age of Surveillance Capitalism: The Fight for a Human Future at the New Frontier of Power. PublicAffairs. — ویکی‌پدیا: Surveillance capitalism.', 'b7981e0d1e36012b89ab28b0e980d9080d175f48de672b426648b5cfa582fa06', 10, NOW(), NOW()),
('sec-new-theory-4-1', 'doc-new-theory-4', 'definition', 'تعریف', 'سرنیک (۲۰۱۷، Platform Capitalism) استدلال می‌کند که پلتفرم‌های دیجیتال (آمازون، آیربی‌انبی، اوبر) فرم جدیدی از سرمایه‌داری هستند که با «مالکیت انحصاری داده» و «اقتصاد شبکه» کار می‌کنند. تفاوت کلیدی با سرمایه‌داری کلاسیک: پلتفرم «زیرساخت مشترک» (common infrastructure) است که همزمان به دو طرف بازار خدمت می‌کند.', 'd3d4ad99433a802856647d298f1c0e6b0d7455f1ca7e876b8d6483be05f845d9', 1, NOW(), NOW()),
('sec-new-theory-4-2', 'doc-new-theory-4', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری سرنیک پلتفرم را «فرم سرمایه‌داری» می‌داند که سه ویژگی دارد: (۱) مالکیت انحصاری داده، (۲) ساختار بازار دوسویه (two-sided market)، (۳) اهرم شبکه‌ای (network effects). این نظریه بر پایه‌ی «اقتصاد توجه» (سایمون) استوار است؛ توجه کاربر را به زیرساخت مشترک تبدیل می‌کند (شبکه ۲).', 'b979ae8d2f28bff3bf4f27fb43f2380f31fe497d9124d4caac3f5aa994ab65c8', 2, NOW(), NOW()),
('sec-new-theory-4-4', 'doc-new-theory-4', 'applications', 'کاربردها', 'تحلیل اقتصاد پلتفرم‌های ایرانی (اسنپ، اسنپ‌فود، دیجی‌کالا) از منظر سرنیک؛ رابطه با «سرمایه‌داری پلتفرمی» (مدخل ۲۲۲) و «اقتصاد بازارهای دوسویه رسانه» (مدخل ۳۸۱)؛ چالش تنظیم‌گری پلتفرم در بافت ایرانی.', '3d050ff5591a1f050f78a4db7847ecf489fdd55c5a35fc70e9c5c166f3e85bcf', 4, NOW(), NOW()),
('sec-new-theory-4-10', 'doc-new-theory-4', 'references', 'منابع', 'Srnicek, N. (2017). Platform Capitalism: The Politics of a New Class Form. Bloomsbury. — ویکی‌پدیا: Platform economy.', 'ffe1bee115a5c5407657e482a9f4e57d13159ef9dc05c13501c8147682987091', 10, NOW(), NOW()),
('sec-new-theory-5-1', 'doc-new-theory-5', 'definition', 'تعریف', 'سایمون در ۱۹۷۱ نوشت: «سرشاری اطلاعات به معنای کمبود توجه است». داونتون و بک (۱۹۹۹، The Attention Economy) مفهوم «اقتصاد توجه» را رسمی کردند: در دنیایی که اطلاعات رایگان است، توجه کاربر کمیاب‌ترین منبع است و رسانه‌ها و پلتفرم‌ها برای کسب آن رقابت می‌کنند.', '95d781e4b5bf4935390d9dac74d922229f5c2ce4fe903053bf0de81f825e53df', 1, NOW(), NOW()),
('sec-new-theory-5-2', 'doc-new-theory-5', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری اقتصاد توجه بر این اصل استوار است که توجه منبع کمیاب و ارزشمند است و رسانه‌ها/پلتفرم‌ها برای «کسب» و «نگه‌داشتن» آن رقابت می‌کنند. این نظریه مبنای مدل‌های کسب‌وکار رسانه دیجیتال (تبلیغات هدفمند، درگیرسازی کاربر، الگوریتم‌های شخصی‌سازی) است و پایه‌ی «اقتصاد پلتفرم» و «سرمایه‌داری نظارتی» می‌شود (شبکه ۲).', '1a2b95d4beed04aaeef0b2ea921e7ef5bcc4d977121909a1793f87a07c6cdfff', 2, NOW(), NOW()),
('sec-new-theory-5-4', 'doc-new-theory-5', 'applications', 'کاربردها', 'تحلیل مدل کسب‌وکار رسانه‌های ایرانی از منظر اقتصاد توجه (مدخل ۳۲)؛ رابطه با «اقتصاد عاطفی» (مدخل ۶۷۶) و «اقتصاد خبر» (مدخل ۴۰)؛ چالش «خستگی رسانه‌ای» مخاطب ایرانی در اقتصاد توجه.', '0f22d244bb3ca37ff6c8ae6cf394ef191932c5f4a46edc0f0f853f1ba733e1f1', 4, NOW(), NOW()),
('sec-new-theory-5-10', 'doc-new-theory-5', 'references', 'منابع', 'Simon, H.A. (1971). Designing Organizations for an Information-Rich World. — Davenport, T.H. & Beck, J.C. (1999). The Attention Economy. Harvard Business School Press.', 'a36d383d9ccebafb704312cff945397d17602e912df348792fb253be907435e9', 10, NOW(), NOW()),
('sec-new-theory-6-1', 'doc-new-theory-6', 'definition', 'تعریف', 'مِرن مِترن (۲۰۱۹) استدلال می‌کند که استخراج داده از جوامع حاشیه (peripheral) توسط شرکت‌های فناوری مرکز (center) فرمی از استعمار نو (neocolonialism) است. داده «خام» از جنوب جهانی استخراج، در شمال پردازش و سود آن به مرکز بازمی‌گردد — شبیه استعمار کلاسیک.', '5a1e95bc25dab4f54d074329f77e2747b972ed999b2a5e3e92997f042628eda9', 1, NOW(), NOW()),
('sec-new-theory-6-2', 'doc-new-theory-6', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری «استعمار داده» سه مرحله دارد: (۱) استخراج داده از حاشیه، (۲) پردازش و ارزش‌آفرینی در مرکز، (۳) بازگشت سود به مرکز. این نظریه پایه‌گذار مباحث «عدالت داده» (data justice) و «حاکمیت داده» (data sovereignty) شد. این فرآیند «شکاف دیجیتال» را تشدید می‌کند: کشورهایی که داده‌شان استخراج می‌شود، در دسترسی به فناوری عقب می‌مانند (شبکه ۳).', '975209f7e4cfb40ffcf461cbae86bf30c0ca91190837a926a39caf6e016db89e', 2, NOW(), NOW()),
('sec-new-theory-6-4', 'doc-new-theory-6', 'applications', 'کاربردها', 'تحلیل ذخیره‌سازی داده‌های ایرانی در سرورهای خارجی (استعمار داده)؛ رابطه با «حاکمیت داده» (مدخل ۵۶) و «عدالت داده» (مدخل ۲۸۴)؛ نقد استخراج داده از پلتفرم‌های ایرانی توسط شرکت‌های خارجی.', '9e571070771f471235d19622ff97639aa29f78bac6b35bf43ae83f89fbcd7f54', 4, NOW(), NOW()),
('sec-new-theory-6-10', 'doc-new-theory-6', 'references', 'منابع', 'Mattern, M. (2019). Data Colonialism, Data Sovereignty, and the Challenge of Geopolitical Mapping in the Age of Digital Extraction. Cartographic Perspective, 91, 59–71. — ویکی‌پدیا: Data colonialism.', '4d8961cbe64fff9ae2fa2eda582399e2f39a1e490068f2a4fb3bda4b76c21612', 10, NOW(), NOW()),
('sec-new-theory-7-1', 'doc-new-theory-7', 'definition', 'تعریف', 'حاکمیت الگوریتمی (Algorithmic Governance) مطالعه‌ی نحوه استفاده از الگوریتم‌ها برای اداره‌ی نظام‌های اجتماعی، اقتصادی و سیاسی است. سرنیک و زاک (۲۰۱۷) «الگوریتم‌های پلتفرمی» را به‌عنوان مکانیسم‌های تصمیم‌گیری پنهان تحلیل کردند. گرِیَم و هاتِر (۲۰۲۰) آن را به «حاکمیت الگوریتمی» گسترش دادند: الگوریتم‌ها نه‌فقط پلتفرم‌ها، بلکه دولت‌ها، نظام‌های قضایی و بهداشتی را اداره می‌کنند.', '87f53742e88c07cd5822eb8776156e223714f87800717e47a3dccd7712fe58f7', 1, NOW(), NOW()),
('sec-new-theory-7-2', 'doc-new-theory-7', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری حاکمیت الگوریتمی سه سطح دارد: (۱) الگوریتم‌های پلتفرمی (سرنیک و زاک)، (۲) حاکمیت الگوریتمی دولت‌ها و مؤسسه‌ها (گرِیَم و هاتِر)، (۳) چالش شفافیت و پاسخگویی. این نظریه مکانیسم فنی «سرمایه‌داری نظارتی» (شبکه ۲) و «تنظیم‌گری/حاکمیت دیجیتال» (شبکه ۶) است.', 'b514828deb77f14e850dbca464ce117df4da0c0c92cdec37556a7831c5c97037', 2, NOW(), NOW()),
('sec-new-theory-7-4', 'doc-new-theory-7', 'applications', 'کاربردها', 'تحلیل الگوریتم‌های فیلترینگ و مدیریت ترافیک اینترنت در ایران؛ رابطه با «حاکمیت الگوریتمی» (مدخل ۲۳۰) و «حاکمیت دیجیتال» (مدخل ۴۰۴)؛ چالش شفافیت الگوریتمی در بافت ایرانی.', '8a6a578c6a353a7ef3d6cd9e1b84ea807e15fdb26628dfd36cd7f15663096f1a', 4, NOW(), NOW()),
('sec-new-theory-7-10', 'doc-new-theory-7', 'references', 'منابع', 'Srnicek, N. & Zuck, J. (2017). Platform Capitalism. Politeia, 1. — Graham, M. & Hutter, K. (2020). Algorithmic Governance: A Framework for Policy Analysis. The International Journal of Information and Communication Technology Policy, 16(2).', 'fdb532e80dbba05f20f8d51617dcb3115399ebee6f7e20948d56245c6edb2ee1', 10, NOW(), NOW()),
('sec-new-theory-8-1', 'doc-new-theory-8', 'definition', 'تعریف', '«پسا-حقیقت» (Post-Truth) وضعیتی است که در آن حقایق عینی کمتر از احساسات و باورهای شخصی بر افکار عمومی تأثیر می‌گذارند. آکسفورد در ۲۰۱۶ آن را «واژه سال» انتخاب کرد. کُسنْتینو (۲۰۲۰، Post-Truth: A New Media Reality) آن را به‌عنوان چارچوب نظری تحلیل کرد: در پسا-حقیقت، «واقعت‌سازی» (reality making) جایگزین «واقعت‌یابی» می‌شود.', '9f39a950f336f3c1bcec9f109e083e7a0688aab2b05ecb7f6d09bd7b85f1fd3f', 1, NOW(), NOW()),
('sec-new-theory-8-2', 'doc-new-theory-8', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری پسا-حقیقت بر این اصل استوار است که احساسات و باورهای شخصی بر حقایق عینی برتری عملی دارند. «حباب فیلتر» (پارِیسِر) مکانیسم فنی آن است: الگوریتم‌ها فقط محتوایی را نشان می‌دهند که با باورهای قبلی کاربر هماهنگ است (شبکه ۴). این فرآیند در بافت پسااستعماری تشدید می‌شود.', '648805f265ae7bf6135e64f586bb141dc15187680ac99b685a091d867fe1ee85', 2, NOW(), NOW()),
('sec-new-theory-8-4', 'doc-new-theory-8', 'applications', 'کاربردها', 'تحلیل جنگ روایت و خبر جعلی در فضای رسانه‌ای ایران؛ رابطه با «عصر پسا-حقیقت» (مدخل ۴۳۸) و «نظریه پستحقیقت» (مدخل ۶۷۳)؛ چالش روزنامه‌نگاری شفاف در عصر پسا-حقیقت.', '7ec091fca7f62b0ca118f53c112343ae10ca051f7f612680d0153195a91e10ff', 4, NOW(), NOW()),
('sec-new-theory-8-10', 'doc-new-theory-8', 'references', 'منابع', 'Cosentino, A. (2020). Post-Truth: A New Media Reality. Cambridge University Press. — Oxford Dictionaries (2016). Post-truth: Word of the Year. — ویکی‌پدیا: Post-truth.', '83c6b610ed2ce765148a9d9bae582404e850d556265a0aa70a6c9a32aa49e63d', 10, NOW(), NOW()),
('sec-new-theory-9-1', 'doc-new-theory-9', 'definition', 'تعریف', 'اشیلر (۱۹۷۵، Mass Communications and American Empire) استدلال کرد که شرکت‌های رسانه‌ای آمریکایی فرمی از امپریالیسم اقتصادی و فرهنگی اجرا می‌کنند: «رسانه به‌عنوان ابزار نفوذ فرهنگی». این نظریه پایه‌گذار مباحث «امپریالیسم فرهنگی» و «هژمونی فرهنگی» شد.', '57dd56d48501e7b2c92d1e95d8c966cff25f926332c2ae4cf3fa2473ef4724b9', 1, NOW(), NOW()),
('sec-new-theory-9-2', 'doc-new-theory-9', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری امپریالیسم رسانه‌ای بر این فرض استوار است که جریان‌های رسانه‌ای یک‌سویه از مرکز (غرب) به حاشیه (شمال) حرکت می‌کنند و فرهنگ محلی را تحت تأثیر قرار می‌دهند. این نظریه در تقابل با «هژمونی فرهنگی» گرامشی/هال قرار دارد: هژمونی فرهنگی ابزار امپریالیسم است (شبکه ۱). زمینه‌ساز آن «جهانی‌شدن فرهنگی» مکلوهان/ترک است.', 'ada568fcf0fdcfb7a8152f4e3fdf55bd79b16c8a042a004c36dbe5ed1dc31406', 2, NOW(), NOW()),
('sec-new-theory-9-4', 'doc-new-theory-9', 'applications', 'کاربردها', 'تحلیل نفوذ محتوای غربی از طریق پلتفرم‌های دیجیتال در ایران؛ رابطه با «امپریالیسم فرهنگی و رسانه‌ای» (مدخل ۹۳) و «هژمونی فرهنگی» (مدخل ۹۱)؛ مقایسه با «نظریه نظام جهانی اطلاعات» (مدخل ۵۱۳).', '0df18d5ac9504f47be61dfe66b03e19e05b3791717f5e226a1489e69a432ece7', 4, NOW(), NOW()),
('sec-new-theory-9-10', 'doc-new-theory-9', 'references', 'منابع', 'Schiller, D.C. (1975). Mass Communications and American Empire. Sage. — ویکی‌پدیا: Media imperialism.', '0bb85fdfe593967916371566c932c0a6548f9c893cfef7f62c4d99aad2d5e62a', 10, NOW(), NOW()),
('sec-new-theory-10-1', 'doc-new-theory-10', 'definition', 'تعریف', '«ارتباطات توسعه» (Development Communication) مکتبی از مطالعات رسانه است که رسانه را ابزاری برای توسعه‌ی اقتصادی و اجتماعی جوامع حاشیه (peripheral) می‌داند. روجِرس و استاینر (۱۹۶۲) «نظریه‌ی دو جریان» (two-flow theory) را مطرح کردند: اطلاعات از مرکز به حاشیه، و از حاشیه به مرکز. جوساوالا (۱۹۷۹) آن را در قالب «ارتباطات دنیای سوم» بازنویسی کرد.', 'a79031a6157691ba9ed17facd487bbe645c5505fa0dbbc9f9ab7ed80d1b116ae', 1, NOW(), NOW()),
('sec-new-theory-10-2', 'doc-new-theory-10', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری ارتباطات توسعه بر این اصل استوار است که رسانه «ابزار توسعه» است و نه صرفاً «انعکاس‌دهنده». «نظریه‌ی دو جریان» (روجِرس/استاینر) جریان دوسویه اطلاعات مرکز-حاشیه را تبیین می‌کند. این نظریه برای تحلیل رسانه به‌عنوان ابزار توسعه در بافت‌های جنوبی کاربرد دارد (شبکه ۵).', 'eacdf98ec80657b0a0a8a784716841bf68d9fbb50f9c79d293fbe3c859b8f313', 2, NOW(), NOW()),
('sec-new-theory-10-4', 'doc-new-theory-10', 'applications', 'کاربردها', 'تحلیل رسانه به‌عنوان ابزار توسعه‌ی اقتصادی و اجتماعی در ایران؛ رابطه با «ارتباطات توسعه و پارادایم نوسازی» (مدخل ۲۳۳) و «روزنامه‌نگاری توسعه» (مدخل ۳۶۴)؛ چالش شکاف دیجیتال (مدخل ۱۲۰) در بافت ایرانی.', '778352570e82e757956c1a2ae572713734b169739738d986d1c711b121b581e3', 4, NOW(), NOW()),
('sec-new-theory-10-10', 'doc-new-theory-10', 'references', 'منابع', 'Rogers, E.M. & Steiner, G.A. (1962). Two-Flow Process: A New Look at International Communication of Ideas. Journal of Communication, 12(1), 41–50. — Jussawalla, A. (1979). Mass Media, Culture and Development. SAGE.', 'db8d4448f510480a4ccdf2c56889eeaa812f5a78914056f603068685af80ead9', 10, NOW(), NOW()),
('sec-new-theory-11-1', 'doc-new-theory-11', 'definition', 'تعریف', 'شکاف دیجیتال (Digital Divide) به نابرابری در دسترسی، استفاده و بهره‌وری از فناوری‌های دیجیتال بین گروه‌های مختلف اشاره دارد. جان ون دییک (۲۰۰۵، The Deepening Divide) آن را در سه سطح تحلیل کرد: دسترسی (access)، استفاده (usage)، و بهره‌وری (benefits).', '9c1227238a58bbabd0a57f855845fbe56d0e5043a458bfb5294e5930b731cb7c', 1, NOW(), NOW()),
('sec-new-theory-11-2', 'doc-new-theory-11', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری شکاف دیجیتال سه سطح دارد: (۱) شکاف دسترسی (digital access)، (۲) شکاف استفاده (digital usage)، (۳) شکاف بهره‌وری (digital benefits). این نظریه در رابطه با «استعمار داده» (مِترن) قرار دارد: کشورهایی که داده‌شان استخراج می‌شود، در دسترسی به فناوری عقب می‌مانند (شبکه ۳). همچنین مانع اصلی «ارتباطات توسعه» (روجِرس/جوساوالا) است (شبکه ۵).', '627cc65f5e56ff15496ce9004d968e32d03baa55a09728bee778e8c2a6eb892f', 2, NOW(), NOW()),
('sec-new-theory-11-4', 'doc-new-theory-11', 'applications', 'کاربردها', 'تحلیل شکاف دیجیتال بین شهر و روستا، بین جوان و پیر در ایران؛ رابطه با «شکاف دیجیتال» (مدخل ۱۲۰) و «فرضیه شکاف دانش» (مدخل ۱۱)؛ چالش عدالت دیجیتال در بافت ایرانی.', '50145dbf5b7a953e68995874bf18b3923f5f766e10b666afecb73c1c1036452b', 4, NOW(), NOW()),
('sec-new-theory-11-10', 'doc-new-theory-11', 'references', 'منابع', 'van Dijk, J.A.G.M. (2005). The Deepening Divide: Inequality in the Information Society. Oxford University Press. — ویکی‌پدیا: Digital divide.', '7d7bbbc5497c361a3ed21b33252dcf192cc48e2881231ec12fcb3a6d810da64d', 10, NOW(), NOW()),
('sec-new-theory-12-1', 'doc-new-theory-12', 'definition', 'تعریف', 'حاکمیت دیجیتال (Digital Governance) مطالعه‌ی چگونگی اداره‌ی فضای دیجیتال توسط دولت‌ها، شرکت‌ها و جامعه مدنی است. «تنظیم‌گری پلتفرمی» (platform regulation) فرم جدیدی از تنظیم‌گری است که به‌جای تنظیم‌کننده‌ی دولت، خود پلتفرم را تنظیم‌کننده می‌داند (self-regulation) (کمیشن اروپا، ۲۰۲۱، Digital Services Act).', '2ae0b6119736fedad7222a48915c5651312cd673982cbab740b8e40132c4fcbb', 1, NOW(), NOW()),
('sec-new-theory-12-2', 'doc-new-theory-12', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری حاکمیت دیجیتال/تنظیم‌گری پلتفرمی سه سطح دارد: (۱) تنظیم‌گری دولت (state regulation)، (۲) خودتنظیمی پلتفرم (self-regulation)، (۳) تنظیم‌گری چندذره‌ای (multi-stakeholder governance). این نظریه بر پایه‌ی «حاکمیت الگوریتمی» (شبکه ۶) استوار است.', 'd0f1a67ee5edd98e312cb977f5fc0f82d3143adbf438772c32607b951ae506d1', 2, NOW(), NOW()),
('sec-new-theory-12-4', 'doc-new-theory-12', 'applications', 'کاربردها', 'تحلیل فیلترینگ و تنظیم‌گری دولت در فضای دیجیتال ایران؛ رابطه با «حاکمیت دیجیتال» (مدخل ۴۰۴) و «تنظیم‌گری پلتفرمی» (مدخل ۴۰۵)؛ چالش «چارچوب حاکمیت اینترنت» (مدخل ۶۴۲) در بافت ایرانی.', '640789d54ba34e572fc8f3f85bbe159e11d4de6229639d4ee08b9fc47b2d187c', 4, NOW(), NOW()),
('sec-new-theory-12-10', 'doc-new-theory-12', 'references', 'منابع', 'European Parliament (2021). Digital Services Act (DSA). — ویکی‌پدیا: Digital governance.', '1f9b5f2f4b7e8490dd8ec1728ec470c9e359f715ec7b79e985e402a3b911378f', 10, NOW(), NOW()),
('sec-new-theory-13-1', 'doc-new-theory-13', 'definition', 'تعریف', 'الی پارِیسِر (۲۰۱۱، The Filter Bubble) مفهوم «حباب فیلتر» را مطرح کرد: الگوریتم‌های پلتفرم‌ها بر اساس تاریخچه‌ی جست‌وجو و رفتار کاربر، محتوای شخصی‌سازی‌شده‌ای را نمایش می‌دهند که کاربر را در «حباب» اطلاعاتی محبوس می‌کند. این فرآیند به قطبی‌سازی (polarization) و کاهش درک مشترک واقعیت می‌انجامد.', '96e24ab00e12451d32fcfa6bb3794e49f3c840d13c1043aecc5e357c1a006ceb', 1, NOW(), NOW()),
('sec-new-theory-13-2', 'doc-new-theory-13', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری حباب فیلتر بر این اصل استوار است که الگوریتم‌های شخصی‌سازی‌کننده، دایره‌ی اطلاعات کاربر را محدود می‌کنند و «واقعیت مشترک» را از بین می‌برند. این نظریه مکانیسم فنی «پسا-حقیقت» (کُسنْتینو) است: الگوریتم‌ها فقط محتوایی را نشان می‌دهند که با باورهای قبلی کاربر هماهنگ است (شبکه ۴). این فرآیند در بافت پسااستعماری (مدخل ۴۶۱) تشدید می‌شود.', '11600adf6584a9e99b8c315ba51e609fe69ac1d36b58047273fec4097eb4c93a', 2, NOW(), NOW()),
('sec-new-theory-13-4', 'doc-new-theory-13', 'applications', 'کاربردها', 'تحلیل الگوریتم‌های شخصی‌سازی‌کننده‌ی پلتفرم‌های ایرانی و خارجی؛ رابطه با «فرهنگ الگوریتمی» (مدخل ۲۲۵) و «تخیل الگوریتمی» (مدخل ۱۱۹)؛ چالش قطبی‌سازی و کاهش درک مشترک در بافت ایرانی.', '89b73d9370aa5f0835515213bae4e9a62f1e84d412c0e776c9582332c5322984', 4, NOW(), NOW()),
('sec-new-theory-13-10', 'doc-new-theory-13', 'references', 'منابع', 'Pariser, E. (2011). The Filter Bubble: What the Internet Is Hiding from You. Penguin. — ویکی‌پدیا: Filter bubble.', 'abafb11406617acd4cb99707d9a7b7a9c75b50052f11b10e5fb4f735f515fac0', 10, NOW(), NOW()),
('sec-new-theory-14-1', 'doc-new-theory-14', 'definition', 'تعریف', 'گرامشی مفهوم «هژمونی فرهنگی» (Cultural Hegemony) را مطرح کرد: حاکمیت نه از طریق زور، بلکه از طریق تفوق فرهنگی و ایدئولوژیک. استیون هال (۱۹۷۳) آن را در قالب «نظریه کدگذاری/بازنمایی» (encoding/decoding) به رسانه‌ها آورد: پیام رسانه‌ای توسط فرستنده کدگذاری، و توسط مخاطب بازنمایی می‌شود.', 'd00432ee91705f497f910b1b5ef63bd58a14cc885879f465c3bb5d88721a3f41', 1, NOW(), NOW()),
('sec-new-theory-14-2', 'doc-new-theory-14', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری کدگذاری/بازنمایی (هال، ۱۹۷۳) سه موقعیت مخاطب را تبیین می‌کند: (۱) موقعیت حاکمانه (dominant)، (۲) موقعیت مقاومتی (oppositional)، (۳) موقعیت مخلوط (negotiated). این نظریه در تقابل با «امپریالیسم رسانه‌ای» (اشیلر) قرار دارد: هژمونی فرهنگی ابزار امپریالیسم است (شبکه ۱).', 'e7eea285b934ca61e93d55db05c577d7042a24e996f63660f52435acdf46f843', 2, NOW(), NOW()),
('sec-new-theory-14-4', 'doc-new-theory-14', 'applications', 'کاربردها', 'تحلیل هژمونی فرهنگی در رسانه‌های ایرانی (تبلیغات دولتی، جنگ روایت)؛ رابطه با «هژمونی فرهنگی» (مدخل ۹۱) و «نظریه پستحقیقت» (مدخل ۶۷۳)؛ چالش بازنمایی رسانه‌ای و مقاومت مخاطب در بافت ایرانی.', '756310e0a1d44dc368acd3e13a2e089489a0058d8b5eb89aac3bf49c68e5bc56', 4, NOW(), NOW()),
('sec-new-theory-14-10', 'doc-new-theory-14', 'references', 'منابع', 'Hall, S. (1973). Encoding/Decoding. Cultural Studies: Selected Issues. — ویکی‌پدیا: Encoding/decoding model.', '5fa4f1f9ea9678e69e2b6853d7f37ac3f3075aa3c2bf25f118b9b88ed97d9672', 10, NOW(), NOW()),
('sec-new-theory-15-1', 'doc-new-theory-15', 'definition', 'تعریف', 'پیام تیرانداز (۱۳۹۷/۲۰۱۸، Soft Power Studies) در این مدل، مبانی نظری «رسانه بهینه» را از اصول اسلامی استخراج می‌کند: صداقت، عدالت، مسئولیت، و احترام به کرامت انسانی. این مدل برخلاف مدل‌های غربی، منبع ارزش‌ها خود را در قرآن و سنت می‌داند.', '44e1702b01fe6b6654d0496f3b14dc00543e2cce640cf68c742f2e25c6ea5b0f', 1, NOW(), NOW()),
('sec-new-theory-15-2', 'doc-new-theory-15', 'theoretical_framework', 'چارچوب نظری', 'چارچوب نظری «مدل بهینه رسانه مبتنی بر اصول اسلامی» چهار اصل بنیادین دارد: (۱) صداقت، (۲) عدالت، (۳) مسئولیت، (۴) احترام به کرامت انسانی. این مدل در بافت ایران می‌تواند مبنای طراحی سیاست‌های رسانه‌ای، اخلاق حرفه‌ای روزنامه‌نگاری، و تنظیم‌گری رسانه قرار گیرد. پاسخی بومی به چالش «ارتباطات توسعه» و «شکاف دیجیتال» در بافت ایرانی است (شبکه ۵).', 'ee2320370f37b932f9f21f5703c8e3ef5db2187ce875a724d37500582e822798', 2, NOW(), NOW()),
('sec-new-theory-15-4', 'doc-new-theory-15', 'applications', 'کاربردها', 'طراحی سیاست‌های رسانه‌ای مبتنی بر اصول اسلامی؛ مبانی اخلاق حرفه‌ای روزنامه‌نگاری در بافت ایرانی؛ تکمیل خلأ «اخلاق رسانه‌ای» (مدخل ۹۷) و «چارچوب اخلاق اقناع» (مدخل ۵۸۲).', 'e17125622a8fa53eaba40c83a8d4b603f94eac7801047783fb5ac268b8d834fa', 4, NOW(), NOW()),
('sec-new-theory-15-10', 'doc-new-theory-15', 'references', 'منابع', 'Tirandaz, P. (2018). Media Policy Model for the Islamic Republic of Iran. Soft Power Studies, 11(3). — spba.ir.', '27e60687bf3cc227b5a2e79df27af35613809c202fe1645b80b8456bd5f920b3', 10, NOW(), NOW());
